"use client";

import {
  useCallback,
  useEffect,
  useId,
  useSyncExternalStore,
  type ElementType,
  type ReactNode,
} from "react";
import {
  BLUR_PRIORITY,
  isBlurGranted,
  registerBlurLayer,
  subscribeBlurBudget,
  unregisterBlurLayer,
  type BlurPriority,
} from "@/lib/surface/blur-budget";
import { useSurface } from "@/lib/surface/SurfaceProvider";

interface GlassSurfaceProps {
  children: ReactNode;
  /**
   * Blur priority. Chrome (nav/tab bars) outranks overlays, which outrank
   * content. When the budget is spent, losers render as a solid fill —
   * visually close, and it keeps scrolling smooth on a budget Android.
   */
  priority?: BlurPriority;
  /**
   * Set on any surface that scrolls its own content. Blurring behind a long
   * scrolling list forces a full-layer recomposite every frame, which is the
   * single most expensive thing we could do on our target hardware.
   */
  scrolls?: boolean;
  as?: ElementType;
  className?: string;
}

/**
 * The floating glass layer.
 *
 * Per the design direction this is for CONTROLS — nav bars, tab bars,
 * floating actions, sheets. Data cards should mostly NOT be translucent, or
 * the layering hierarchy collapses and everything reads at the same depth.
 * If you are reaching for GlassSurface to wrap a data card, use a plain
 * `bg-surface` card instead.
 */
export function GlassSurface({
  children,
  priority = BLUR_PRIORITY.content,
  scrolls = false,
  as: Tag = "div",
  className = "",
}: GlassSurfaceProps) {
  const { mode } = useSurface();

  // Only `glass` mode is eligible for blur at all; solid and contrast never
  // register, which leaves the budget free for surfaces that can use it.
  const eligible = mode === "glass" && !scrolls;
  const id = useId();

  useEffect(() => {
    if (!eligible) return;
    registerBlurLayer(id, priority);
    return () => unregisterBlurLayer(id);
  }, [eligible, priority, id]);

  const getSnapshot = useCallback(
    () => eligible && isBlurGranted(id),
    [eligible, id],
  );
  const blurred = useSyncExternalStore(
    subscribeBlurBudget,
    getSnapshot,
    () => false, // Server render is always solid; blur is a client concern.
  );

  return (
    <Tag
      data-glass={blurred ? "blur" : "solid"}
      className={className}
      style={{
        background: "var(--glass-fill)",
        backdropFilter: blurred ? "var(--glass-filter)" : undefined,
        WebkitBackdropFilter: blurred ? "var(--glass-filter)" : undefined,
        boxShadow: "inset 0 1px 0 0 var(--glass-border), var(--glass-shadow)",
        borderRadius: "var(--radius-parent)",
      }}
    >
      {children}
    </Tag>
  );
}
